package io.github.jesterportfolio.hearth.combat;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;

final class CombatRestartTest {
    static final class Fixture {
        final CombatPlayersTest.Fixture f=new CombatPlayersTest.Fixture();final CompletableFuture<Void> saved=new CompletableFuture<>();final AtomicInteger starts=new AtomicInteger();boolean valid=true,backendFail;
        final CombatContent.Retry policy=new CombatContent.Retry("BOSS_ONLY",new FieldContent.Point(7,64,8),31,12,0.5,List.of());
        final CombatRetryVote.Receipt receipt;final CombatRestart restart;
        Fixture(){f.bridge.died(f.p);f.fight.finish(CombatAttempt.Outcome.RETRY);receipt=new CombatRetryVote.Receipt(f.run,f.fight.snapshot().attempt(),UUID.randomUUID());restart=new CombatRestart(f.fight,policy,List.of(f.p,f.q),()->saved,roster->{starts.incrementAndGet();if(backendFail)throw new IllegalStateException("SPAWN_FAILED");return new CombatAttempt(f.run,f.world,1,CombatAttemptTest.content(Pool.SHARED,2,LocationMode.START),roster,new CombatAttemptTest.Actors(),f.owner,()->{},f.clock::get);},f.owner,()->{},()->valid&&f.generation.get()==1);}
        void prepare(){saved.complete(null);f.pump();}void apply(){f.p.applying.complete(true);f.pump();f.q.applying.complete(true);f.pump();}
    }
    @Test void saveThenEveryApplyThenNewAttemptAndCountersAreConfirmedOnce(){var x=new Fixture();var before=x.f.p.inventory.clone();var work=x.restart.begin(x.receipt);assertSame(work,x.restart.begin(x.receipt));x.f.pump();assertEquals(0,x.f.p.restores);assertEquals(CombatRestart.Phase.SAVING,x.restart.phase());assertFalse(x.restart.barrier().toCompletableFuture().isDone());x.prepare();assertEquals(1,x.f.p.restores);assertEquals(0,x.f.q.restores);assertEquals(0,x.starts.get());x.apply();var next=work.toCompletableFuture().join();assertEquals(CombatRestart.Phase.STARTED,x.restart.phase());assertFalse(x.f.p.applyGuard.getAsBoolean());assertFalse(x.f.q.applyGuard.getAsBoolean());assertNotEquals(x.f.fight.snapshot().attempt(),next.snapshot().attempt());assertEquals(2,next.snapshot().difficultyPlayers());assertTrue(next.snapshot().members().stream().noneMatch(m->m.dead()||m.used()>0));assertEquals(0,next.snapshot().sharedUsed());assertEquals(0.5,x.f.p.health);assertEquals(x.policy.pose(x.f.world),x.f.p.position);assertArrayEquals(before,x.f.p.inventory);assertSame(work,x.restart.begin(x.receipt));assertEquals(1,x.starts.get());}
    @Test void saveFailureNeverAppliesOrCreatesAndPreservesOldResult(){var x=new Fixture();var work=x.restart.begin(x.receipt);x.saved.completeExceptionally(new IllegalStateException("DB_FAILED"));x.f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRestart.Phase.HOLD,x.restart.phase());assertEquals(0,x.f.p.restores);assertEquals(0,x.starts.get());assertTrue(x.restart.barrier().toCompletableFuture().isCompletedExceptionally());assertEquals(CombatAttempt.Outcome.RETRY,x.f.fight.snapshot().outcome());}
    @Test void unsafeLocationAndFalseApplyCannotStartAnotherAttempt(){for(boolean unsafe:List.of(true,false)){var x=new Fixture();x.f.p.safe=!unsafe;var work=x.restart.begin(x.receipt);x.prepare();if(!unsafe){x.f.p.applying.complete(false);x.f.pump();assertFalse(x.f.p.applyGuard.getAsBoolean());}assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.starts.get());assertEquals(CombatRestart.Phase.HOLD,x.restart.phase());}}
    @Test void worldGenerationOrSessionInvalidationPreventsLateMoveAndCreation(){for(boolean world:List.of(true,false)){var x=new Fixture();var work=x.restart.begin(x.receipt);x.prepare();if(world)x.f.generation.incrementAndGet();else x.f.p.live=false;assertFalse(x.f.p.applyGuard.getAsBoolean());x.apply();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.starts.get());assertEquals(1,x.f.p.health);}}
    @Test void shutdownGuardStopsLateApplicationWithoutRetrying(){var x=new Fixture();var work=x.restart.begin(x.receipt);x.prepare();x.restart.close();assertFalse(x.f.p.applyGuard.getAsBoolean());x.apply();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.starts.get());assertEquals(CombatRestart.Phase.HOLD,x.restart.phase());}
    @Test void backendFailureDoesNotReportStartedOrRepeatRequest(){var x=new Fixture();x.backendFail=true;var work=x.restart.begin(x.receipt);x.prepare();x.apply();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRestart.Phase.HOLD,x.restart.phase());assertSame(work,x.restart.begin(x.receipt));assertEquals(1,x.starts.get());}
    @Test void wrongReceiptAndDifferentDuplicateAreRejected(){var x=new Fixture();assertTrue(x.restart.begin(new CombatRetryVote.Receipt(UUID.randomUUID(),x.receipt.attempt(),x.receipt.request())).toCompletableFuture().isCompletedExceptionally());var work=x.restart.begin(x.receipt);assertTrue(x.restart.begin(new CombatRetryVote.Receipt(x.receipt.run(),x.receipt.attempt(),UUID.randomUUID())).toCompletableFuture().isCompletedExceptionally());x.prepare();x.apply();assertFalse(work.toCompletableFuture().isCompletedExceptionally());}
    @Test void invalidPolicyAndMixedRunRosterFailBeforeAnyWork(){var x=new Fixture();assertThrows(IllegalArgumentException.class,()->new CombatContent.Retry("FROM_PATH",new FieldContent.Point(1,64,1),0,0,0.5,List.of()));assertThrows(IllegalArgumentException.class,()->new CombatContent.Retry("BOSS_ONLY",new FieldContent.Point(1,64,1),0,0,0,List.of()));var other=new CombatPlayersTest.Fixture();assertThrows(IllegalArgumentException.class,()->new CombatRestart(x.f.fight,x.policy,List.of(other.p),()->x.saved,r->x.f.fight,x.f.owner,()->{},()->true));}
    @Test void unconfirmedOldAttemptCannotBeRestarted(){var x=new Fixture();var active=new CombatPlayersTest.Fixture();var restart=new CombatRestart(active.fight,x.policy,List.of(active.p),()->x.saved,r->active.fight,active.owner,()->{},()->true);assertTrue(restart.begin(new CombatRetryVote.Receipt(active.run,active.fight.snapshot().attempt(),UUID.randomUUID())).toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRestart.Phase.IDLE,restart.phase());}
    @Test void rejectedOwnerDeliveryHoldsWithoutGameApplication(){var x=new Fixture();x.f.reject.set(true);var work=x.restart.begin(x.receipt);assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRestart.Phase.HOLD,x.restart.phase());assertEquals(0,x.starts.get());}
    @Test void legacyContentRemainsWithoutRetryAndUnsupportedOrIncompletePolicyIsRejected(){
        var revival=Map.of("enabled",true,"condition","rescue","pool","SHARED","limit",2,"health-fraction",0.5,"location","START","effects",List.of());
        var root=new HashMap<String,Object>(Map.of("format",1,"id","trial","title","공개 시험","health-per-player",20,"attack",2,"return-protection-ms",3000,"revival",revival));
        assertNull(CombatContent.parse(root).retry());var retry=new HashMap<String,Object>(Map.of("scope","BOSS_ONLY","entry",Map.of("x",3.5,"y",64,"z",3.5,"yaw",0,"pitch",0),"health-fraction",0.5,"effects",List.of()));root.put("retry",retry);
        assertEquals("BOSS_ONLY",CombatContent.parse(root).retry().scope());retry.put("scope","FROM_PATH");assertThrows(IllegalArgumentException.class,()->CombatContent.parse(root));retry.put("scope","BOSS_ONLY");retry.remove("entry");assertThrows(IllegalArgumentException.class,()->CombatContent.parse(root));
    }
    @Test void previousPlayerGuardClosesBeforeNextPreparation(){var x=new Fixture();x.restart.begin(x.receipt);x.prepare();assertTrue(x.f.p.applyGuard.getAsBoolean());x.f.p.applying.complete(true);x.f.pump();assertFalse(x.f.p.applyGuard.getAsBoolean());assertTrue(x.f.q.applyGuard.getAsBoolean());x.restart.close();assertFalse(x.f.q.applyGuard.getAsBoolean());}
}
